'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I18N=MacroI18n, t=value=>I18N.t(value);
let blackWhite=false;try{blackWhite=localStorage.getItem('macro-black-white')==='true'}catch{}
const GRAYS=['#111111','#666666','#999999','#333333','#BBBBBB','#777777','#DDDDDD'];
function gray(hex){const c=hex.replace('#','');const v=Math.round(.2126*parseInt(c.slice(0,2),16)+.7152*parseInt(c.slice(2,4),16)+.0722*parseInt(c.slice(4,6),16)).toString(16).padStart(2,'0');return v.repeat(3)}
const COLORS=['#285ae1','#759bfd','#08287f','#d92214','#8696b6','#51a89a','#a298d8'];
const FED='https://www.cmegroup.com/markets/interest-rates/cme-fedwatch-tool.html';
let DATA, charts=[], page='', previewIndex=0, activeDetail=null, newsRegion='全部';
let selection=[];try{selection=JSON.parse(localStorage.getItem('macro-report-v1')||'[]')}catch{}
const DEF={
 tw_signal:{name:'台灣景氣燈號',group:'台灣經濟',ids:['tw_signal'],period:'12',signal:true},
 tw_cpi_categories:{name:'台灣最新一月CPI分類',group:'台灣經濟',ids:['tw_cpi'],period:'latest',category:true,type:'bar'},
 tw_cpi:{name:'台灣CPI與核心CPI',group:'台灣經濟',ids:['tw_cpi','tw_core'],period:'24'},
 tw_gdp:{name:'台灣實質GDP年增率',group:'台灣經濟',ids:['tw_gdp'],period:'120',type:'bar'},
 tw_industry:{name:'台灣工業與製造業生產',group:'台灣經濟',ids:['tw_industry','tw_manufacturing'],period:'24'},
 tw_trade:{name:'台灣進出口與貿易順差',group:'台灣經濟',ids:['tw_exports','tw_imports','tw_balance'],period:'24'},
 tw_orders:{name:'台灣外銷訂單年增率',group:'台灣經濟',ids:['tw_orders_yoy'],period:'24',type:'bar'},
 tw_unemployment:{name:'台灣失業率',group:'台灣經濟',ids:['tw_unemployment','tw_unemployment_sa'],period:'24'},
 tw_reserves:{name:'台灣外匯存底',group:'台灣經濟',ids:['tw_reserves'],period:'24'},
 tw_stock:{name:'台灣加權指數',group:'台灣經濟',ids:['tw_stock'],period:'all'},
 tw_short:{name:'台灣政策與短期利率',group:'利率動向',ids:['tw_policy','tw_overnight','tw_taibor'],period:'12'},
 tw_long:{name:'台灣10年期公債利率（月）',group:'利率動向',ids:['tw_10y'],period:'60'},
 us_curve:{name:'美國2年與10年公債殖利率',group:'美國經濟',ids:['us_2y','us_10y'],period:'12'},
 us_spread:{name:'美債10年－2年利差',group:'美國經濟',ids:['us_spread'],period:'24'},
 us_cpi:{name:'美國CPI與核心CPI',group:'美國經濟',ids:['us_cpi','us_core'],period:'24'},
 us_payroll:{name:'美國非農就業月增人數',group:'美國經濟',ids:['us_payroll'],period:'24',type:'bar'},
 us_payroll_total:{name:'美國非農就業總人數',group:'美國經濟',ids:['us_payroll_total'],period:'24'},
 us_gdp:{name:'美國實質GDP季增年率',group:'美國經濟',ids:['us_gdp'],period:'120',type:'bar'},
 usdtwd:{name:'新台幣兌美元匯率',group:'外匯動向',ids:['usdtwd'],period:'3'},
 usdjpy:{name:'美元兌日圓匯率',group:'外匯動向',ids:['usdjpy'],period:'12'},
 twdjpy:{name:'新台幣兌日圓匯率',group:'外匯動向',ids:['twdjpy'],period:'12'},
 broad_usd:{name:'廣義美元指數（非DXY）',group:'外匯動向',ids:['broad_usd'],period:'12'}
};
function valid(k){const d=DEF[k];return d&&(d.category?DATA.cpiCategories?.points?.length:d.ids.some(i=>DATA.series[i]?.points?.length))}
function fmt(v,d=2){return Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—'}
function localTime(t){return t?new Date(t).toLocaleString(I18N.locale(),{timeZone:'Asia/Taipei',hour12:false}):'未提供'}
function toast(msg){$('#toast').textContent=t(msg);$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(){try{localStorage.setItem('macro-report-v1',JSON.stringify(selection))}catch{}$('#nav-count').textContent=selection.length?`· ${selection.length}`:''}
function dispose(){charts.forEach(c=>c.dispose());charts=[]}
function rangeLabel(p){return p==='latest'?'最新已公布月份':p==='all'?'全部可用資料':p==='120'?'近10年':`最近${p}個月`}
function rawSpec(key,period,normalized=false){
 const d=DEF[key];period=period||d.period;
 if(d.category){const c=DATA.cpiCategories;if(!c)return null;return {key,title:d.name,type:'bar',category:true,unit:c.unit,dates:c.points.map(p=>p[0]),series:[{name:'各類別年增率',values:c.points.map(p=>p[1])}],source:c.source,url:c.url,from:c.period,to:c.period,note:'與去年同月相比；依官方最新月報分類。',published:c.published,checkedAt:c.checkedAt,period};}
 const all=d.ids.map(id=>DATA.series[id]).filter(Boolean);if(!all.length)return null;
 let last=all.map(s=>s.points.at(-1)[0]).sort().at(-1);let cutoff='0000';
 if(period!=='all'){let dt=new Date(last+'T12:00:00Z');dt.setUTCMonth(dt.getUTCMonth()-Number(period));cutoff=dt.toISOString().slice(0,10)}
 let dates=[...new Set(all.flatMap(s=>s.points.filter(p=>p[0]>=cutoff).map(p=>p[0])))].sort();
 if(d.signal&&period==='12')dates=dates.slice(-12);
 const ss=all.map(s=>{const m=new Map(s.points);let prior=s.points.filter(p=>p[0]<dates[0]).at(-1)?.[1];let values=dates.map(date=>{if(m.has(date))prior=m.get(date);return s.id==='tw_policy'||s.id==='us_policy'?prior??null:m.get(date)??null});if(normalized){let b=values.find(v=>v!==null&&v!==0);values=values.map(v=>v===null?null:b?v/b*100:null)}return {name:s.title,values,id:s.id}});
 // Hide policy rate steps only if no changes in window by carrying last effective setting.
 return {key,title:d.name,type:d.type||'line',unit:normalized?'基期 = 100':all[0].unit,dates,series:ss,source:[...new Set(all.map(s=>s.source))].join('、'),url:all[0].url,from:dates[0],to:dates.at(-1),note:all.map(s=>s.note).filter(Boolean).join(' '),published:all[0].published,checkedAt:all.map(s=>s.checkedAt).sort()[0],period,signal:d.signal,normalized};
}
function getSpec(key,period,normalized=false){
 const sp=rawSpec(key,period,normalized);if(!sp)return null;
 return {...sp,title:t(sp.title),unit:t(sp.unit),rawUnit:sp.unit,source:t(sp.source),note:t(sp.note),dates:sp.category?sp.dates.map(t):sp.dates,series:sp.series.map(v=>({...v,name:t(v.name)}))};
}

function signal(v){return v<=16?['藍燈','#3f74e6']:v<=22?['黃藍燈','#b6af42']:v<=31?['綠燈','#2a9b78']:v<=37?['黃紅燈','#ebaa32']:['紅燈','#e36363']}
function chartOption(spec,compact=false){
 if(!spec)return {};const isCat=spec.category;const palette=spec.monochrome?GRAYS:COLORS;
 const option={animation:false,color:palette,textStyle:{fontFamily:I18N.language==='JP'?'DM Sans, Noto Sans JP, sans-serif':'DM Sans, Noto Sans TC, sans-serif'},grid:{left:compact?37:49,right:compact?15:22,top:compact?28:49,bottom:compact?31:62,containLabel:false},tooltip:{trigger:'axis',confine:true,backgroundColor:'#fff',borderColor:'#e4eaf5',textStyle:{color:'#334766',fontSize:11},valueFormatter:v=>v==null?'—':fmt(v,spec.unit==='千人'?0:2)},legend:{show:spec.series.length>1,top:5,itemWidth:13,itemHeight:3,textStyle:{color:'#7c8ca6',fontSize:compact?8:10}},xAxis:{type:'category',data:spec.dates,boundaryGap:spec.type==='bar',axisLine:{lineStyle:{color:'#e9edf5'}},axisTick:{show:false},axisLabel:{fontSize:compact?8:10,color:'#98a3b7',hideOverlap:true,formatter:(v)=>isCat?v:spec.signal?v.slice(2,7).replace('-','/'):v.slice(0,7),rotate:isCat?20:0}},yAxis:{type:'value',scale:!spec.signal,splitNumber:4,min:spec.signal?9:undefined,max:spec.signal?45:undefined,name:spec.unit,nameTextStyle:{color:'#98a3b7',fontSize:9,align:'left'},axisLabel:{fontSize:compact?8:10,color:'#98a3b7'},splitLine:{lineStyle:{color:'#eff2f8',type:'dashed'}}},dataZoom:compact?[]:[{type:'inside'},{type:'slider',height:14,bottom:8,borderColor:'#edf1f7',fillerColor:'#285ae115',handleStyle:{color:'#759bfd'},textStyle:{fontSize:8},showDetail:false}],series:spec.series.map((s,i)=>({name:s.name,type:spec.type,data:s.values.map(v=>spec.signal?{value:v,itemStyle:{color:spec.monochrome?'#222222':signal(v)[1]}}:v),smooth:false,connectNulls:false,showSymbol:!!spec.signal,symbolSize:spec.signal?7:4,lineStyle:{width:2,type:spec.monochrome?['solid','dashed','dotted'][i%3]:'solid'},barMaxWidth:isCat?34:24,itemStyle:{borderRadius:spec.type==='bar'?[3,3,0,0]:0},areaStyle:spec.series.length===1&&spec.type!=='bar'?{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:spec.monochrome?'#2222221c':'#285ae11c'},{offset:1,color:spec.monochrome?'#22222201':'#285ae101'}])}:undefined}))};
 if(spec.signal){option.series[0].markArea={silent:true,itemStyle:{opacity:.05},data:[[{yAxis:9,itemStyle:{color:'#3f74e6'}},{yAxis:16.5}],[{yAxis:16.5,itemStyle:{color:'#b6af42'}},{yAxis:22.5}],[{yAxis:22.5,itemStyle:{color:'#2a9b78'}},{yAxis:31.5}],[{yAxis:31.5,itemStyle:{color:'#ebaa32'}},{yAxis:37.5}],[{yAxis:37.5,itemStyle:{color:'#e36363'}},{yAxis:45}]]};}
 if(spec.monochrome&&spec.signal){option.series[0].markArea.data.forEach((band,i)=>band[0].itemStyle.color=['#dddddd','#bbbbbb','#999999','#777777','#555555'][i]);}
 if(spec.key==='us_spread')option.series[0].markLine={symbol:'none',silent:true,label:{show:false},lineStyle:{color:'#aebbd2',type:'dashed'},data:[{yAxis:0}]};
 return option;
}
function draw(el,spec,compact=false){if(!el)return;if(!spec||!spec.dates.length){el.innerHTML='<div class="data-empty">尚未取得可用資料<br>請查看來源更新狀態</div>';return}const c=echarts.init(el,null,{renderer:'canvas'});c.setOption(chartOption(spec,compact));charts.push(c);return c}
function actions(key){return `<div class="chart-actions"><button data-detail="${key}" title="展開圖表" aria-label="展開${DEF[key].name}">⤢</button><button data-add="${key}" title="加入報告" aria-label="${esc(I18N.language==='CH'?'將'+DEF[key].name+'加入報告':I18N.language==='EN'?'Add '+t(DEF[key].name)+' to report':t(DEF[key].name)+'をレポートに追加')}">＋</button></div>`}
function panel(key,opts={}){const spec=getSpec(key,opts.period);return `<section class="panel"><div class="panel-top"><div><h3>${esc(opts.title||DEF[key].name)}</h3><div class="sub">${esc(opts.subtitle||rangeLabel(opts.period||DEF[key].period))}</div></div>${actions(key)}</div>${opts.signal&&spec?`<div class="signal-summary"><strong>${fmt(spec.series[0].values.at(-1),0)}<span class="sub"> 分</span></strong><span class="signal-name" style="color:${signal(spec.series[0].values.at(-1))[1]}">${signal(spec.series[0].values.at(-1))[0]}</span><span class="sub">${spec.to.slice(0,7)} · 最新已公布月份</span></div>`:''}<div class="chart ${opts.large?'large':''}" data-chart="${key}" ${opts.period?`data-period="${opts.period}"`:''}></div><div class="panel-foot"><span>${esc(spec?.source||'官方資料')}</span><span>${esc(spec?.to||'來源暫未回應')}${spec?.category?'':' 截至'}</span></div></section>`}
function card(id,label,key){const s=DATA.series[id];const ps=s?.points||[];const a=ps.at(-1),b=ps.at(-2);const unit=s?.unit||'%';const digits=unit==='點'||unit==='千人'?0:id==='tw_overnight'||id==='tw_taibor'?3:2;const change=a&&b?a[1]-b[1]:null;const tag=change===null?'尚無前期比較':`${change>0?'↗':change<0?'↘':'→'} ${fmt(Math.abs(change),digits)} ${unit==='%'?'百分點':unit} · 較前期`;
 const vals=ps.slice(-18).map(p=>p[1]);let svg='';if(vals.length>1){const min=Math.min(...vals),max=Math.max(...vals);const path=vals.map((v,i)=>`${i/(vals.length-1)*84},${29-(v-min)/(max-min||1)*25}`).join(' ');svg=`<svg class="spark" viewBox="0 0 86 32" aria-hidden="true"><polyline points="${path}" fill="none" stroke="#759bfd" stroke-width="1.7"/></svg>`}
 return `<article class="stat-card" tabindex="0" role="button" data-detail="${key}" aria-label="${esc(I18N.language==='CH'?'查看'+(label||s?.title||id)+'圖表':I18N.language==='EN'?'View '+t(label||s?.title||id)+' chart':t(label||s?.title||id)+'を表示')}"><div class="stat-top"><span>${esc(label||s?.title||id)}</span><span class="tiny">${esc(s?.frequency||'')}資料</span></div><div class="stat-value">${a?fmt(a[1],digits):'—'}<em>${esc(unit)}</em></div><div class="stat-bottom"><span class="change ${change>0?'rise':change<0?'fall':''}">${tag}</span>${svg}</div><div class="sub">${a?esc(a[0].slice(0,s.frequency==='日'?10:7)):'資料待更新'}</div></article>`;
}
function hero(eyebrow,title,sub,report=false){const d=new Date(DATA.generatedAt);return `<section class="hero"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="hero-right">${report?'<span class="pill">POWERPOINT · 原生可編輯圖表</span>':`<div class="date">${d.toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'})}</div><div class="muted">最後檢查 ${d.toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false})} · 台灣時間</div>`}</div></section>`}
function section(title,en,right=''){return `<div class="section-head"><h2>${title}<span class="country-label">${en}</span></h2>${right}</div>`}
function renderNews(){const rows=DATA.news.filter(n=>newsRegion==='全部'||n.region===newsRegion).slice(0,4);return rows.length?rows.map(n=>`<a class="news-item" href="${esc(n.url)}" target="_blank" rel="noopener"><div class="meta"><span>${esc(n.date)}</span><span>${esc(n.source)}</span></div><h4>${esc(I18N.news(n))} ↗</h4></a>`).join(''):'<div class="empty">目前沒有可用的官方消息</div>'}
function dashboard(){const failures=DATA.sources.filter(s=>s.status!=='ok').length;return hero('TAIWAN × GLOBAL · ECONOMIC OBSERVATORY','看見數據背後的經濟脈動','台灣與美國經濟指標、利率與外匯，一站掌握。')+`<div class="update-strip"><span class="pill ${failures?'warn':'green'}">${failures?'部分來源待更新':'資料已檢查'}</span><span>${Object.keys(DATA.series).length} 組官方指標 · 每張圖表皆可互動、下載與加入報告</span><span>下次檢查：每日 21:30 TST</span></div>`+section('<span class="country-icon">TW</span>台灣經濟','TAIWAN', '<p>最新已公布數據 · 點擊卡片探索</p>')+`<div class="stats">${card('tw_gdp','實質GDP年增率','tw_gdp')}${card('tw_cpi','CPI年增率','tw_cpi')}${card('tw_industry','工業生產年增率','tw_industry')}${card('tw_unemployment_sa','失業率（季調）','tw_unemployment')}${card('tw_exports','出口金額','tw_trade')}${card('tw_orders_yoy','外銷訂單年增率','tw_orders')}${card('tw_reserves','外匯存底','tw_reserves')}${card('usdtwd','新台幣兌美元','usdtwd')}</div><div class="two-col">${panel('tw_signal',{signal:true,period:'12',subtitle:'近12個月 · 綜合判斷分數與官方燈號'})}<section class="panel"><div class="panel-top"><div><h3>重點消息</h3><div class="sub">官方發布 · 回到資訊的源頭</div></div><div class="tabs" id="news-tabs">${['全部','台灣','美國'].map(x=>`<button class="${newsRegion===x?'active':''}" data-news="${x}">${x}</button>`).join('')}</div></div><div id="news-list">${renderNews()}</div></section></div>`+section('<span class="country-icon">US</span>美國經濟與利率預期','UNITED STATES','<p>通膨、就業、成長與資金價格</p>')+`<div class="us-layout"><section class="panel fedwatch"><div><div class="eyebrow">MARKET EXPECTATIONS</div><h3 style="font-size:23px;margin-top:12px">下一步，Fed怎麼走？</h3><p>前往 CME FedWatch 查看下一次FOMC會議的升息、降息與維持利率機率。</p></div><a class="button" href="${FED}" target="_blank" rel="noopener">開啟 CME FedWatch <span>↗</span></a><small>市場隱含預期 · 官方工具入口</small></section><div class="us-stats">${card('us_10y','10年期公債殖利率','us_curve')}${card('us_2y','2年期公債殖利率','us_curve')}${card('us_cpi','CPI年增率','us_cpi')}${card('us_core','核心CPI年增率','us_cpi')}${card('us_payroll','非農就業月增人數','us_payroll')}${card('us_gdp','實質GDP季增年率','us_gdp')}</div></div><div class="market-panels">${panel('us_curve')}${panel('us_cpi')}</div>`+section('接下來，關注什麼？','RELEASE CALENDAR','<a class="button small" href="https://www.stat.gov.tw/News_NoticeCalendar.aspx?n=3717" target="_blank" rel="noopener">台灣官方發布日曆 ↗</a>')+`<section class="panel">${DATA.calendar?.length?DATA.calendar.map(n=>`<a class="calendar-row" href="${esc(n.url)}" target="_blank" rel="noopener"><span class="cal-date">${esc(n.date.slice(5).replace('-','/'))}</span><div><p>${esc(n.title)}</p><span class="sub">${esc(n.source)} · ${esc(n.note)}</span></div></a>`).join(''):'<p class="sub">預告日期請見各機關官方發布日曆。</p>'}</section>`}
function rates(){return hero('INTEREST RATES · POLICY & MARKETS','利率動向','從央行政策到公債殖利率，觀察資金價格的變化。')+section('台灣：政策與市場','TAIWAN')+`<div class="stats">${card('tw_policy','央行重貼現率','tw_short')}${card('tw_overnight','隔夜拆款利率','tw_short')}${card('tw_taibor','3個月TAIBOR','tw_short')}${card('tw_10y','10年期公債（月）','tw_long')}</div><div class="market-panels">${panel('tw_short',{large:true})}${panel('tw_long',{large:true})}</div><div class="insight">台灣10年期公債採央行月資料，與每日美債報價的發布頻率不同。政策利率在生效後維持到下一次調整。</div>`+section('美國：殖利率與期限結構','UNITED STATES')+`<div class="market-panels">${panel('us_curve',{large:true})}${panel('us_spread',{large:true})}</div><div class="insight">10年－2年利差低於零表示殖利率曲線倒掛。可搭配CPI、非農就業與FedWatch觀察，避免將單一指標視為買賣訊號。</div><div class="toolbar"><a class="button" href="${FED}" target="_blank" rel="noopener">CME FedWatch ↗</a><a class="button" href="https://www.cbc.gov.tw/tw/lp-302-1.html" target="_blank" rel="noopener">台灣央行政策消息 ↗</a></div>`}
function fx(){return hero('FOREIGN EXCHANGE · TRENDS & CONTEXT','外匯動向','看清報價方向、觀測時點與匯率變化。')+`<div class="stats">${card('usdtwd','新台幣兌美元','usdtwd')}${card('usdjpy','美元兌日圓','usdjpy')}${card('twdjpy','新台幣兌日圓','twdjpy')}${card('broad_usd','廣義美元指數','broad_usd')}</div><div class="market-panels">${panel('usdtwd',{large:true,subtitle:'近3個月 · 1美元可兌換的新台幣'})}${panel('usdjpy',{large:true,subtitle:'1美元可兌換的日圓 · Fed週發布參考資料'})}${panel('twdjpy',{large:true,subtitle:'1新台幣可兌換的日圓 · 同日資料交叉計算'})}${panel('broad_usd',{large:true,subtitle:'Fed廣義美元指數 · 不同於ICE DXY'})}</div><div class="insight">USD/TWD上升代表新台幣對美元貶值。日圓與廣義美元指數採Fed發布資料，存在發布落差；交叉匯率使用同日但不同報價時點的資料，僅作參考。</div>`}
function addToReport(key){if(!valid(key)){toast('這張圖表暫無可用資料');return}if(selection.some(x=>x.key===key)){toast('這張圖表已在報告中');return}selection.push({key,period:DEF[key].period,normalized:false});persist();toast('已加入報告，可至「報告製作」調整順序');if(page==='report')render()}
function report(){selection=selection.filter(x=>DEF[x.key]);previewIndex=Math.max(0,Math.min(previewIndex,selection.length-1));persist();return hero('REPORT STUDIO · SELECT, ARRANGE, EXPORT','讓數據，直接成為你的簡報。','選擇圖表、設定期間、拖曳排序，下載一份可以繼續編輯的PowerPoint。',true)+`<div class="report-intro"><span class="step"><b>1</b>勾選需要的圖表</span><span class="step-arrow">→</span><span class="step"><b>2</b>拖曳調整順序與期間</span><span class="step-arrow">→</span><span class="step"><b>3</b>預覽並下載PPT</span><button class="button small" id="example-report" style="margin-left:auto">套用範例三頁</button></div><div class="report-grid"><section class="panel"><div class="report-col-head"><h3>圖表資料庫</h3><small>${Object.keys(DEF).length} 張圖表</small></div><input id="catalog-search" class="search" placeholder="搜尋指標或圖表…" aria-label="搜尋圖表"><div id="catalog">${['台灣經濟','美國經濟','利率動向','外匯動向'].map(group=>`<div class="catalog-group"><div class="group-title">${group}</div>${Object.entries(DEF).filter(([k,d])=>d.group===group).map(([k,d])=>`<label class="catalog-item" data-name="${esc(d.name)}"><input type="checkbox" data-select="${k}" ${selection.some(s=>s.key===k)?'checked':''} ${valid(k)?'':'disabled'}><span>${esc(d.name)}<small>${valid(k)?rangeLabel(d.period):'尚未取得資料'}</small></span></label>`).join('')}</div>`).join('')}</div></section><section class="panel"><div class="report-col-head"><h3>投影片順序</h3><small>${selection.length} 頁</small></div><div id="order-list">${selection.length?selection.map((s,i)=>`<div class="order-item ${i===previewIndex?'active':''}" draggable="true" data-order="${i}" tabindex="0" role="button" aria-label="第${i+1}頁 ${DEF[s.key].name}"><span class="order-num">⠿ ${String(i+1).padStart(2,'0')}</span><div class="order-title">${esc(DEF[s.key].name)}<small>${rangeLabel(s.period)}</small><div class="order-buttons"><button data-move="${i},-1" title="向前移" aria-label="第${i+1}頁向前移" ${i===0?'disabled':''}>↑</button><button data-move="${i},1" title="向後移" aria-label="第${i+1}頁向後移" ${i===selection.length-1?'disabled':''}>↓</button><button data-remove="${i}" title="移除" aria-label="移除第${i+1}頁">×</button></div></div></div>`).join(''):'<div class="empty">從左側勾選圖表<br>開始建立你的報告</div>'}</div>${selection.length?'<button class="button ghost" id="clear-report" style="font-size:10px">清空選擇</button>':''}</section><section class="panel report-preview-panel"><div class="report-col-head"><h3>投影片預覽</h3><small>16:9 · 一頁一張圖</small></div><div class="slide-shell"><div class="slide-preview ${blackWhite?'monochrome':''}" id="slide-preview">${selection.length?`<h3 id="slide-title"></h3><div class="slide-sub" id="slide-sub"></div><div class="chart" id="slide-chart"></div><div class="slide-bottom"><span id="slide-source"></span><span>${String(previewIndex+1).padStart(2,'0')} / ${String(selection.length).padStart(2,'0')}</span></div>`:'<div class="empty" style="margin:auto">你的下一份經濟簡報，從這裡開始。<br>勾選左側圖表，即可預覽投影片。</div>'}</div></div><div class="preview-nav"><button id="prev-slide" aria-label="上一頁" ${previewIndex<=0?'disabled':''}>‹</button><span>${selection.length?previewIndex+1:0} / ${selection.length}</span><button id="next-slide" aria-label="下一頁" ${previewIndex>=selection.length-1?'disabled':''}>›</button></div>${selection.length?`<div class="preview-settings"><span>本頁期間</span><select id="report-period" aria-label="投影片圖表期間">${periodOptions(selection[previewIndex].period,DEF[selection[previewIndex].key].category)}</select>${DEF[selection[previewIndex].key].group==='外匯動向'?`<label><input type="checkbox" id="report-normalize" ${selection[previewIndex].normalized?'checked':''}> 基期100</label>`:''}</div>`:''}<div class="export-preferences"><label for="report-black-white"><input type="checkbox" id="report-black-white" ${blackWhite?'checked':''}> 黑白</label><small>套用至整份PPT與預覽</small></div><div class="report-export"><button class="button primary" id="download-ppt" ${!selection.length?'disabled':''}>↓ 下載可編輯PPTX <span>${selection.length?`· ${selection.length}頁`:''}</span></button><button class="button" id="download-image" ${!selection.length?'disabled':''}>下載本頁單圖</button></div><p class="report-note">圖表、數值、標題與來源文字均可在PowerPoint編輯。<br>預覽依相同資料與版型呈現；字型與間距可能因軟體略異。<br>圖表選擇僅儲存在此瀏覽器，不上傳個人內容。</p></section></div>`}
function periodOptions(p,cat=false){return (cat?[['latest','最新已公布月份']]:[['3','近3個月'],['6','近6個月'],['12','近12個月'],['24','近2年'],['60','近5年'],['120','近10年'],['all','全部可用資料']]).map(([v,t])=>`<option value="${v}" ${p===v?'selected':''}>${t}</option>`).join('')}
function render(){dispose();page=location.hash.slice(1)||'dashboard';if(!['dashboard','rates','fx','report'].includes(page))page='dashboard';$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#main').innerHTML=({dashboard,rates,fx,report})[page]();$$('[data-chart]').forEach(el=>draw(el,getSpec(el.dataset.chart,el.dataset.period),true));bindCommon();if(page==='report')bindReport();persist();I18N.dom()}
function bindCommon(){ $$('[data-detail]').forEach(el=>{el.onclick=()=>openDetail(el.dataset.detail);if(el.tagName==='ARTICLE')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail(el.dataset.detail)}}});$$('[data-add]').forEach(el=>el.onclick=()=>addToReport(el.dataset.add));$$('[data-news]').forEach(el=>el.onclick=()=>{newsRegion=el.dataset.news;$$('[data-news]').forEach(x=>x.classList.toggle('active',x.dataset.news===newsRegion));$('#news-list').innerHTML=renderNews();I18N.dom($('#news-list'))})}
function bindReport(){
 $$('[data-select]').forEach(x=>x.onchange=()=>{if(x.checked)addToReport(x.dataset.select);else{selection=selection.filter(s=>s.key!==x.dataset.select);persist();render()}});
 $('#catalog-search').oninput=e=>{$$('.catalog-item').forEach(x=>x.style.display=(x.dataset.name+' '+t(x.dataset.name)).toLowerCase().includes(e.target.value.toLowerCase())?'':'none')};
 $('#report-black-white').onchange=e=>{blackWhite=e.target.checked;try{localStorage.setItem('macro-black-white',String(blackWhite))}catch{}render()};
 $('#example-report').onclick=()=>{selection=['tw_signal','tw_cpi_categories','usdtwd'].filter(valid).map(key=>({key,period:DEF[key].period,normalized:false}));previewIndex=0;persist();render()};
 $$('[data-remove]').forEach(x=>x.onclick=e=>{e.stopPropagation();selection.splice(+x.dataset.remove,1);persist();render()});
 $$('[data-move]').forEach(x=>x.onclick=e=>{e.stopPropagation();const [i,d]=x.dataset.move.split(',').map(Number);[selection[i],selection[i+d]]=[selection[i+d],selection[i]];previewIndex=i+d;persist();render()});
 let drag=null;$$('[data-order]').forEach(x=>{x.onclick=()=>{previewIndex=+x.dataset.order;render()};x.onkeydown=e=>{if(e.key==='Enter'){previewIndex=+x.dataset.order;render()}};const handle=x.querySelector('.order-num');let start=null;handle.onpointerdown=e=>{start={x:e.clientX,y:e.clientY,index:+x.dataset.order};handle.setPointerCapture(e.pointerId);e.preventDefault();e.stopPropagation()};handle.onpointermove=e=>{if(!start)return;$$('[data-order]').forEach(v=>v.classList.remove('drag-over'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-order]');if(target)target.classList.add('drag-over')};handle.onpointerup=e=>{if(!start)return;const initial=start;start=null;$$('[data-order]').forEach(v=>v.classList.remove('drag-over'));if(Math.hypot(e.clientX-initial.x,e.clientY-initial.y)<8)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-order]');if(target){const to=+target.dataset.order;if(to!==initial.index){const [item]=selection.splice(initial.index,1);selection.splice(to,0,item);previewIndex=to;persist();render()}}};handle.onpointercancel=()=>{start=null;$$('[data-order]').forEach(v=>v.classList.remove('drag-over'))};x.ondragstart=e=>{drag=+x.dataset.order;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(drag))};x.ondragover=e=>{e.preventDefault();x.classList.add('drag-over')};x.ondragleave=()=>x.classList.remove('drag-over');x.ondrop=e=>{e.preventDefault();let to=+x.dataset.order;if(drag!==null&&drag!==to){let [s]=selection.splice(drag,1);selection.splice(to,0,s);previewIndex=to;persist();render()}}});
 $('#prev-slide').onclick=()=>{previewIndex--;render()};$('#next-slide').onclick=()=>{previewIndex++;render()};$('#clear-report')?.addEventListener('click',()=>{selection=[];persist();render()});
 $('#report-period')?.addEventListener('change',e=>{selection[previewIndex].period=e.target.value;persist();render()});$('#report-normalize')?.addEventListener('change',e=>{selection[previewIndex].normalized=e.target.checked;persist();render()});
 if(selection.length){const s=selection[previewIndex],sp=getSpec(s.key,s.period,s.normalized);if(sp){$('#slide-title').textContent=sp.title;$('#slide-sub').textContent=`${sp.category?sp.to.slice(0,7):`${sp.from} — ${sp.to}`} ｜ ${sp.unit}${sp.normalized?' ｜ 各序列首個有效值=100':''}`;$('#slide-source').textContent=`資料來源：${sp.source}`;draw($('#slide-chart'),{...sp,monochrome:blackWhite},true)}}
 $('#download-ppt').onclick=async()=>{const b=$('#download-ppt');b.disabled=true;b.textContent=t('正在製作PPT…');try{await exportPpt(selection);toast('可編輯PPTX已下載')}catch(e){console.error(e);toast('匯出失敗，請重試：'+e.message)}finally{b.disabled=false;b.textContent=t(`↓ 下載可編輯PPTX · ${selection.length}頁`)}};
 $('#download-image').onclick=()=>{const s=selection[previewIndex];downloadImage({...getSpec(s.key,s.period,s.normalized),monochrome:blackWhite})};
}
function openDetail(key){if(!DEF[key])return;activeDetail={key,period:DEF[key].period,normalized:false};$('#detail-group').textContent=DEF[key].group;$('#detail-title').textContent=DEF[key].name;$('#detail-controls').innerHTML=`<div class="toolbar"><label>期間 <select id="detail-period">${periodOptions(activeDetail.period,DEF[key].category)}</select></label>${DEF[key].group==='外匯動向'?'<label><input type="checkbox" id="detail-normalize"> 基期100</label>':''}<button class="button small right" id="detail-add">＋ 加入報告</button><button class="button small" id="detail-png">↓ 單圖</button><button class="button small" id="detail-csv">CSV</button></div>`;$('#chart-dialog').showModal();paintDetail();$('#detail-period').onchange=e=>{activeDetail.period=e.target.value;paintDetail()};$('#detail-normalize')?.addEventListener('change',e=>{activeDetail.normalized=e.target.checked;paintDetail()});$('#detail-add').onclick=()=>{const {key,period,normalized}=activeDetail;addToReport(key);let s=selection.find(s=>s.key===key);if(s){s.period=period;s.normalized=normalized;persist()}};$('#detail-png').onclick=()=>downloadImage(getSpec(key,activeDetail.period,activeDetail.normalized));$('#detail-csv').onclick=()=>downloadCsv(getSpec(key,activeDetail.period,activeDetail.normalized));I18N.dom($('#chart-dialog'))}
function paintDetail(){const {key,period,normalized}=activeDetail;const sp=getSpec(key,period,normalized);const old=echarts.getInstanceByDom($('#detail-chart'));if(old){old.dispose();charts=charts.filter(c=>c!==old)}draw($('#detail-chart'),sp);$('#detail-foot').innerHTML=sp?`<div><a href="${esc(sp.url)}" target="_blank" rel="noopener">${esc(sp.source)} ↗</a><br>${esc(sp.note)}<br>官方發布：${esc(sp.published||'來源未提供獨立發布日期')} · 最後成功檢查：${esc(localTime(sp.checkedAt))}</div>`:'目前無可用資料；請查看來源更新狀態。';I18N.dom($('#chart-dialog'))}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
function downloadCsv(sp){if(!sp)return toast('暫無資料可匯出');const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=[[t('日期／分類'),...sp.series.map(s=>s.name)],...sp.dates.map((d,i)=>[d,...sp.series.map(s=>s.values[i])]),[],[t('來源'),sp.source],[t('來源網址'),sp.url],[t('單位'),sp.unit]];downloadBlob(new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),sp.title+'.csv')}
function downloadImage(sp){if(!sp)return toast('暫無資料可匯出');const el=document.createElement('div');el.style.cssText='position:fixed;left:-10000px;width:1600px;height:900px';document.body.appendChild(el);const c=echarts.init(el);let o=chartOption(sp);o.backgroundColor='#fff';o.title={text:sp.title,subtext:`${sp.from} — ${sp.to} ｜ ${sp.unit}`,left:50,top:25,textStyle:{color:sp.monochrome?'#111111':'#08287f',fontSize:26},subtextStyle:{fontSize:13}};o.grid={...o.grid,top:130,bottom:110,left:90,right:60};o.legend={...o.legend,top:88};o.dataZoom=[];o.graphic=[{type:'text',left:50,bottom:25,style:{text:`${t('資料來源：')}${sp.source} ｜ ${t('最後成功檢查：')}${localTime(sp.checkedAt)}`,fill:sp.monochrome?'#666666':'#8593aa',fontSize:12}}];c.setOption(o);const u=c.getDataURL({type:'png',pixelRatio:1});const a=document.createElement('a');a.href=u;a.download=sp.title+'.png';a.click();c.dispose();el.remove();toast('圖表PNG已下載')}
async function exportPpt(items){
 const p=new PptxGenJS();const mono=blackWhite, lang=I18N.locale(),font=I18N.font();const ink=mono?'111111':'08287F',muted=mono?'666666':'8593AA',rule=mono?'CCCCCC':'E6EAF2';
 p.layout='LAYOUT_WIDE';p.author='Macro Lens';p.subject=t('官方總體經濟指標');p.title=t('總體經濟觀測報告');p.company='Macro Lens';p.lang=lang;p.theme={headFontFace:font,bodyFontFace:font,lang};
 for(let i=0;i<items.length;i++){
  const it=items[i],sp=getSpec(it.key,it.period,it.normalized);if(!sp||!sp.dates.length)throw Error(t(DEF[it.key].name)+' — '+t('尚未取得資料'));
  const slide=p.addSlide();slide.background={color:'FFFFFF'};
  slide.addShape(p.ShapeType.rect,{x:0,y:0,w:13.333,h:.07,fill:{color:mono?'111111':'285AE1'},line:{color:mono?'111111':'285AE1'}});
  slide.addText(sp.title,{x:.6,y:.35,w:12,h:.52,fontFace:font,fontSize:I18N.language==='EN'&&sp.title.length>36?22:24,bold:true,color:ink,margin:0,fit:'shrink'});
  slide.addText(`${sp.from} — ${sp.to}  |  ${sp.unit}${sp.normalized?'  |  '+t('各序列首個有效值=100'):''}`,{x:.6,y:.96,w:12,h:.28,fontSize:10,color:muted,margin:0,fit:'shrink'});
  const native=sp.series.map((s,j)=>({name:s.name,labels:sp.dates.map(d=>sp.category?d:d.slice(0,10)),values:s.values,...(mono?{options:{lineDashType:['solid','dash','dot'][j%3]}}:{})}));
  slide.addChart(sp.type==='bar'?p.ChartType.bar:p.ChartType.line,native,{
   x:.55,y:1.45,w:12.05,h:4.85,catAxisLabelFontFace:font,valAxisLabelFontFace:font,catAxisLabelFontSize:sp.category?10:9,valAxisLabelFontSize:10,
   catAxisLabelColor:muted,valAxisLabelColor:muted,showLegend:sp.series.length>1,legendPos:'t',legendFontFace:font,legendFontSize:11,legendColor:muted,
   chartColors:(mono?GRAYS:COLORS).map(x=>x.slice(1)),showTitle:false,showValue:false,showMarker:!!sp.signal,markerSize:6,lineSize:2,
   showBorder:false,catAxisLineColor:rule,valAxisLineColor:'FFFFFF',catAxisLabelFrequency:sp.category?1:Math.max(1,Math.ceil(sp.dates.length/10)),
   valGridLine:{color:mono?'DDDDDD':'EEF1F6',width:.6},showLine:true,valAxisMinVal:sp.signal?9:undefined,valAxisMaxVal:sp.signal?45:undefined,
   showShadow:false,showPlotArea:false,showChartArea:false,showSerName:false,catAxisLabelPos:'low',barDir:'col',grouping:'clustered'
  });
  if(sp.signal)slide.addText(t('燈號分數：藍 9–16 ｜ 黃藍 17–22 ｜ 綠 23–31 ｜ 黃紅 32–37 ｜ 紅 38–45'),{x:.65,y:6.35,w:11.9,h:.25,fontSize:9,color:muted,margin:0,fit:'shrink'});
  slide.addShape(p.ShapeType.line,{x:.6,y:6.75,w:12.1,h:0,line:{color:rule,width:.7}});
  slide.addText(`${t('資料來源：')}${sp.source}\n${sp.url}`,{x:.6,y:6.87,w:9.7,h:.35,fontSize:7,color:muted,margin:0,breakLine:false,...(!mono?{hyperlink:{url:sp.url}}:{})});
  slide.addText(`${i+1} / ${items.length}`,{x:11.7,y:6.91,w:1,h:.2,fontSize:9,color:muted,align:'right',margin:0});
  slide.addNotes(`${t('官方資料；資料期間')} ${sp.from} — ${sp.to}.\n${sp.note}\n${t('最後成功檢查：')}${sp.checkedAt}\n${t('官方發布：')}${sp.published||t('來源未另提供')}\n${t('PowerPoint圖表內嵌數據可編輯。')}`);
 }
 await p.writeFile({fileName:`MacroLens_${I18N.language}_${t('經濟報告')}_${new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'})}${mono?'_BW':''}.pptx`});
}

function showStatus(){const stale=Date.now()-new Date(DATA.generatedAt)>36*3600000;$('#status-content').innerHTML=`<p class="sub">${DATA.delivery==='snapshot'?'目前顯示網站備份資料；線上資料暫不可用。<br>':''}最近執行：${localTime(DATA.generatedAt)}<br>每日21:30（台灣時間）排程；可能受GitHub服務負載延遲。${stale?'<br><b class="error-text">距上次檢查已超過36小時，請查看GitHub Actions。</b>':''}</p><div class="status-row"><b>指標／來源</b><b>最新資料期間</b><b>最後成功檢查</b></div>${Object.values(DATA.series).map(s=>`<div class="status-row"><span>${esc(s.title)}<small><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.source)} ↗</a></small></span><span>${esc(s.latestDate)}<small>${s.frequency}資料</small></span><span>${esc(localTime(s.checkedAt))}</span></div>`).join('')}<h3>本次來源檢查</h3>${DATA.sources.map(s=>`<p class="sub ${s.status==='ok'?'':'error-text'}">${s.status==='ok'?'✓':'△'} ${esc(s.name)}：${s.status==='ok'?'已檢查':t('來源暫時無法取得；保留上次有效資料')+' ('+esc((s.message||'').match(/\b[45]\d{2}\b/)?.[0]||'network')+')'}</p>`).join('')}<a href="https://github.com/between-lines-lab/Macro-economics-web/actions" target="_blank" rel="noopener">查看更新紀錄 ↗</a>`;I18N.dom($('#status-dialog'));$('#status-dialog').showModal()}
function changeLanguage(lang){
 I18N.set(lang);try{const u=new URL(location.href);u.searchParams.set('lang',I18N.language);history.replaceState(null,'',u)}catch{}
 $$('.language-switch button').forEach(b=>{b.classList.toggle('active',b.dataset.lang===I18N.language);b.setAttribute('aria-pressed',String(b.dataset.lang===I18N.language))});
 if($('#chart-dialog').open)$('#chart-dialog').close();if($('#status-dialog').open)$('#status-dialog').close();if(DATA)render();else I18N.dom();
}
$$('[data-lang]').forEach(b=>b.onclick=()=>changeLanguage(b.dataset.lang));changeLanguage(I18N.language);
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});window.addEventListener('resize',()=>charts.forEach(c=>{if(!c.isDisposed())c.resize()}));$('#close-chart').onclick=()=>$('#chart-dialog').close();$('#close-status').onclick=()=>$('#status-dialog').close();$('#status-button').onclick=showStatus;$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
fetch('https://api.github.com/repos/between-lines-lab/Macro-economics-web/contents/dist/data/macro.json?ref=main',{headers:{Accept:'application/vnd.github.raw+json'},cache:'no-cache',signal:AbortSignal.timeout(10000)}).then(r=>{if(!r.ok)throw Error('資料來源暫不可用');return r.json()}).then(d=>d.content?JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(d.content.replace(/\s/g,'')),c=>c.charCodeAt(0)))):d).catch(()=>fetch('https://raw.githubusercontent.com/between-lines-lab/Macro-economics-web/main/dist/data/macro.json?t='+Math.floor(Date.now()/60000),{cache:'no-cache',signal:AbortSignal.timeout(10000)}).then(r=>{if(!r.ok)throw Error('線上資料暫不可用');return r.json()})).catch(()=>fetch('data/macro.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('資料檔載入失敗');return r.json()}).then(d=>{d.delivery='snapshot';return d})).then(d=>{DATA=d;render();if(d.delivery==='snapshot')toast('線上資料暫時無法取得，顯示隨網站保存的最近資料')}).catch(e=>{$('#main').innerHTML=`<section class="panel"><h2>資料暫時無法載入</h2><p>${esc(e.message)}</p><button class="button" onclick="location.reload()">重新載入</button></section>`});
